88	func (d *DB) ListUsers(ctx context.Context, find *store.FindUser) ([]*store.User, error) {
89		where, args := []string{"1 = 1"}, []any{}
90		orderBy := []string{"created_ts DESC", "row_status DESC", "id DESC"}
91	
92		if len(find.Filters) > 0 {
93			return nil, errors.Errorf("user filters are not supported")
94		}
95	
96		if v := find.ID; v != nil {
97			where, args = append(where, "id = ?"), append(args, *v)
98		}
99		if len(find.IDList) > 0 {
100			placeholders := make([]string, 0, len(find.IDList))
101			for range find.IDList {
102				placeholders = append(placeholders, "?")
103			}
104			where, args = append(where, fmt.Sprintf("id IN (%s)", strings.Join(placeholders, ", "))), append(args, func() []any {
105				list := make([]any, 0, len(find.IDList))
106				for _, id := range find.IDList {
107					list = append(list, id)
108				}
109				return list
110			}()...)
111		}
112		if len(find.UsernameList) > 0 {
113			placeholders := make([]string, 0, len(find.UsernameList))
114			for range find.UsernameList {
115				placeholders = append(placeholders, "?")
116			}
117			where, args = append(where, fmt.Sprintf("username IN (%s)", strings.Join(placeholders, ", "))), append(args, func() []any {
118				list := make([]any, 0, len(find.UsernameList))
119				for _, username := range find.UsernameList {
120					list = append(list, username)
121				}
122				return list
123			}()...)
124		}
125		if v := find.RowStatus; v != nil {
126			where, args = append(where, "row_status = ?"), append(args, *v)
127		}
128		if v := find.Username; v != nil {
129			where, args = append(where, "username = ?"), append(args, *v)
130		}
131		if v := find.Role; v != nil {
132			where, args = append(where, "role = ?"), append(args, *v)
133		}
134		if v := find.Email; v != nil {
135			where, args = append(where, "email = ?"), append(args, *v)
136		}
137		if v := find.Nickname; v != nil {
138			where, args = append(where, "nickname = ?"), append(args, *v)
139		}
140		if v := find.Search; v != nil && strings.TrimSpace(*v) != "" {
141			query := strings.ToLower(strings.TrimSpace(*v))
142			where, args = append(where, "(LOWER(username) LIKE ? OR LOWER(nickname) LIKE ?)"), append(args, "%"+query+"%", "%"+query+"%")
143			orderBy = []string{
144				"CASE WHEN LOWER(username) = ? THEN 0 WHEN LOWER(username) LIKE ? THEN 1 WHEN LOWER(nickname) LIKE ? THEN 2 ELSE 3 END",
145				"LENGTH(username) ASC",
146				"created_ts DESC",
147				"row_status DESC",
148			}
149			args = append(args, query, query+"%", query+"%")
150		}
151		query := `
152			SELECT 
153				id,
154				username,
155				role,
156				email,
157				nickname,
158				password_hash,
159				avatar_url,
160				description,
161				created_ts,
162				updated_ts,
163				row_status
164			FROM user
165			WHERE ` + strings.Join(where, " AND ") + ` ORDER BY ` + strings.Join(orderBy, ", ")
166		if v := find.Limit; v != nil {
167			query += fmt.Sprintf(" LIMIT %d", *v)
168			if v := find.Offset; v != nil {
169				query += fmt.Sprintf(" OFFSET %d", *v)
170			}
171		}
172	
173		rows, err := d.db.QueryContext(ctx, query, args...)
174		if err != nil {
175			return nil, err
176		}
177		defer rows.Close()
178	
179		list := make([]*store.User, 0)
180		for rows.Next() {
181			var user store.User
182			if err := rows.Scan(
183				&user.ID,
184				&user.Username,
185				&user.Role,
186				&user.Email,
187				&user.Nickname,
188				&user.PasswordHash,
189				&user.AvatarURL,
190				&user.Description,
191				&user.CreatedTs,
192				&user.UpdatedTs,
193				&user.RowStatus,
194			); err != nil {
195				return nil, err
196			}
197			list = append(list, &user)
198		}
199	
200		if err := rows.Err(); err != nil {
201			return nil, err
202		}
203	
204		return list, nil
205	}
